<script lang="ts" setup>
import { computed, onMounted, ref } from 'vue';
import { Alert as AAlert, Button as AButton, Card as ACard, Drawer as ADrawer, Form as AForm, FormItem as AFormItem, InputNumber as AInputNumber, Popconfirm as APopconfirm, Select as ASelect, Switch as ASwitch, Table as ATable, Tag as ATag, message } from 'ant-design-vue';
import MetricGrid from '#/components/operations/MetricGrid.vue';
import { type PageResult, useServerPagination } from '#/utils/server-pagination';
import SectionHelp from '#/components/openresty/SectionHelp.vue';
type Center={id:string;name:string;code:string}; type Scope='HTTP'|'STREAM'|'HTTP_SERVER'|'HTTP_LOCATION'|'STREAM_SERVER'; type Resolver={id:string;scope:Scope;targetResourceId?:string;resolverAddresses:string[];validSeconds:number;timeoutMilliseconds:number;ipv6Enabled:boolean;enabled:boolean}; type Server={id:string;domain:string;listenPort:number}; type Location={id:string;path:string}; type StreamServer={id:string;serviceName:string;listenPort:number};
const centers=ref<Center[]>([]),values=ref<Resolver[]>([]),rows=ref<Resolver[]>([]),httpServers=ref<Server[]>([]),locations=ref<{id:string;label:string}[]>([]),streamServers=ref<StreamServer[]>([]); const centerId=ref<string>(),drawerOpen=ref(false),editingId=ref<string>(),loading=ref(false); const pager=useServerPagination();
const fresh=()=>({scope:'HTTP' as Scope,targetResourceId:undefined as string|undefined,resolverAddresses:['127.0.0.11'] as string[],validSeconds:30,timeoutMilliseconds:3000,ipv6Enabled:false,enabled:true}); const form=ref(fresh());
const scopeOptions=[{value:'HTTP',label:'HTTP 全局（HTTP）'},{value:'STREAM',label:'Stream 全局（STREAM）'},{value:'HTTP_SERVER',label:'HTTP 虚拟主机（HTTP_SERVER）'},{value:'HTTP_LOCATION',label:'HTTP 路由（HTTP_LOCATION）'},{value:'STREAM_SERVER',label:'Stream 服务（STREAM_SERVER）'}];
const scopeLabel=(v:Scope)=>scopeOptions.find(x=>x.value===v)?.label||v; const targetOptions=computed(()=>form.value.scope==='HTTP_SERVER'?httpServers.value.map(x=>({value:x.id,label:`${x.domain}:${x.listenPort}`})):form.value.scope==='HTTP_LOCATION'?locations.value.map(x=>({value:x.id,label:x.label})):form.value.scope==='STREAM_SERVER'?streamServers.value.map(x=>({value:x.id,label:`${x.serviceName}:${x.listenPort}`})):[]); const needsTarget=computed(()=>!['HTTP','STREAM'].includes(form.value.scope));
const columns=[{key:'scope',title:'作用域'},{key:'target',title:'目标'},{dataIndex:'resolverAddresses',key:'addresses',title:'DNS 地址'},{dataIndex:'validSeconds',key:'valid',title:'缓存'},{key:'status',title:'状态'},{key:'action',title:'操作',width:130}];
const reportMetrics=computed(()=>[{label:'Resolver 配置',value:values.value.length,suffix:'条',hint:`${values.value.filter(x=>x.enabled).length} 条已启用`,tone:'blue'},{label:'DNS 服务器地址',value:new Set(values.value.flatMap(x=>x.resolverAddresses)).size,suffix:'个',hint:'已配置的唯一地址',tone:'cyan'},{label:'全局作用域',value:values.value.filter(x=>['HTTP','STREAM'].includes(x.scope)).length,suffix:'条',hint:'HTTP / Stream',tone:'green'},{label:'精细作用域',value:values.value.filter(x=>!['HTTP','STREAM'].includes(x.scope)).length,suffix:'条',hint:'Server / Location',tone:'purple'}]);
async function request<T>(path:string,options?:RequestInit):Promise<T>{const r=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(options?.headers||{})}});if(!r.ok){const b=await r.json().catch(()=>({}));throw new Error(b.detail||b.message||'请求失败')}return r.status===204?undefined as T:r.json()}
async function loadPage(){if(!centerId.value)return;rows.value=pager.apply(await request<PageResult<Resolver>>(`/centers/${centerId.value}/dns-resolvers/paged?${pager.query()}`))}
async function changePage(p:any){pager.change(p);await loadPage()}
async function selectCenter(id:string){centerId.value=id;pager.reset();loading.value=true;try{const [r,h,s]=await Promise.all([request<Resolver[]>(`/centers/${id}/dns-resolvers`),request<Server[]>(`/centers/${id}/http/servers`),request<StreamServer[]>(`/centers/${id}/stream/servers`)]);values.value=r;await loadPage();httpServers.value=h;streamServers.value=s;const groups=await Promise.all(h.map(async server=>(await request<Location[]>(`/centers/${id}/http/servers/${server.id}/locations`)).map(x=>({id:x.id,label:`${server.domain}:${server.listenPort}${x.path}`}))));locations.value=groups.flat()}catch(e){message.error(e instanceof Error?e.message:'加载 Resolver 失败')}finally{loading.value=false}}
async function load(){centers.value=await request<Center[]>('/centers');if(centers.value[0])await selectCenter(centers.value[0].id)}
function open(value?:Resolver){editingId.value=value?.id;form.value=value?{scope:value.scope,targetResourceId:value.targetResourceId,resolverAddresses:[...value.resolverAddresses],validSeconds:value.validSeconds,timeoutMilliseconds:value.timeoutMilliseconds,ipv6Enabled:value.ipv6Enabled,enabled:value.enabled}:fresh();drawerOpen.value=true}
function scopeChanged(){form.value.targetResourceId=undefined}
async function save(){if(!centerId.value)return;if(needsTarget.value&&!form.value.targetResourceId){message.warning('请选择配置目标');return}try{await request(`/centers/${centerId.value}/dns-resolvers${editingId.value?`/${editingId.value}`:''}`,{method:editingId.value?'PUT':'POST',body:JSON.stringify(form.value)});drawerOpen.value=false;await selectCenter(centerId.value);message.success('Resolver 配置已保存')}catch(e){message.error(e instanceof Error?e.message:'保存失败')}}
async function remove(id:string){if(!centerId.value)return;await request(`/centers/${centerId.value}/dns-resolvers/${id}`,{method:'DELETE'});await selectCenter(centerId.value);message.success('Resolver 配置已删除')}
function targetLabel(v:Resolver){if(!v.targetResourceId)return '全局';return [...httpServers.value.map(x=>({id:x.id,label:`${x.domain}:${x.listenPort}`})),...locations.value,...streamServers.value.map(x=>({id:x.id,label:`${x.serviceName}:${x.listenPort}`}))].find(x=>x.id===v.targetResourceId)?.label||'目标已删除'}
onMounted(load);
</script>
<template><div class="ops-page"><a-card title="DNS Resolver 配置" :bordered="false"><template #extra><section-help text="Resolver 可配置在 HTTP、Stream、Server 或 Location 层级；下级配置会覆盖上级配置。"/></template><div class="flex justify-between gap-4"><a-select v-model:value="centerId" class="w-80" :options="centers.map(x=>({value:x.id,label:`${x.name}（${x.code}）`}))" @change="selectCenter"/><a-button type="primary" :disabled="!centerId" @click="open()">新增 DNS Resolver</a-button></div></a-card><metric-grid :metrics="reportMetrics"/><a-card :bordered="false"><a-table :columns="columns" :data-source="rows" :loading="loading" row-key="id" :pagination="pager.table.value" @change="changePage"><template #bodyCell="{column,record}"><template v-if="column.key==='scope'">{{scopeLabel(record.scope)}}</template><template v-else-if="column.key==='target'">{{targetLabel(record)}}</template><template v-else-if="column.key==='addresses'"><a-tag v-for="address in record.resolverAddresses" :key="address" color="blue">{{address}}</a-tag></template><template v-else-if="column.key==='valid'">{{record.validSeconds}} 秒</template><template v-else-if="column.key==='status'"><a-tag :color="record.enabled?'green':'default'">{{record.enabled?'启用':'停用'}}</a-tag></template><template v-else-if="column.key==='action'"><a-button type="link" @click="open(record)">编辑</a-button><a-popconfirm title="确认删除该 Resolver？" @confirm="remove(record.id)"><a-button danger type="link">删除</a-button></a-popconfirm></template></template></a-table></a-card><a-drawer v-model:open="drawerOpen" :title="editingId?'编辑 DNS Resolver':'新增 DNS Resolver'" :width="600"><a-alert class="mb-4" type="info" show-icon message="DNS 服务器地址必须能够从 OpenResty 节点访问；缓存过期后会按配置重新解析域名。"/><a-form layout="vertical"><a-form-item label="作用域" required><a-select v-model:value="form.scope" :options="scopeOptions" @change="scopeChanged"/></a-form-item><a-form-item v-if="needsTarget" label="配置目标" required><a-select v-model:value="form.targetResourceId" show-search :options="targetOptions"/></a-form-item><a-form-item label="DNS 服务器地址" required extra="支持多个 IPv4 或 IPv6 地址；输入一个地址后按回车，可继续添加。"><a-select v-model:value="form.resolverAddresses" mode="tags" placeholder="例如 127.0.0.11、10.0.0.53 或 [2001:db8::53]" :token-separators="[',',' ']"/></a-form-item><a-form-item label="缓存有效期（秒）"><a-input-number v-model:value="form.validSeconds" class="w-full" :min="1" :max="3600"/></a-form-item><a-form-item label="解析超时（毫秒）"><a-input-number v-model:value="form.timeoutMilliseconds" class="w-full" :min="100" :max="60000"/></a-form-item><a-form-item label="IPv6"><a-switch v-model:checked="form.ipv6Enabled" checked-children="启用" un-checked-children="关闭"/></a-form-item><a-form-item label="状态"><a-switch v-model:checked="form.enabled" checked-children="启用" un-checked-children="停用"/></a-form-item></a-form><template #footer><div class="flex justify-end gap-2"><a-button @click="drawerOpen=false">取消</a-button><a-button type="primary" @click="save">保存</a-button></div></template></a-drawer></div></template>
